<?php
session_start();
if (!isset($_SESSION['divisi']) || $_SESSION['divisi'] !== 'akunting') { header('Location: ../index.php'); exit; }
require_once '../config/database.php';

$periode = $_GET['periode'] ?? 'bulan';
$valid = ['hari','minggu','bulan','tahun'];
if (!in_array($periode, $valid, true)) $periode = 'bulan';
$where = "t.created_at >= DATE_TRUNC('month', CURRENT_DATE) AND t.created_at < DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month'";
if ($periode === 'hari') $where = "t.created_at >= CURRENT_DATE AND t.created_at < CURRENT_DATE + INTERVAL '1 day'";
elseif ($periode === 'minggu') $where = "t.created_at >= DATE_TRUNC('week', CURRENT_DATE) AND t.created_at < DATE_TRUNC('week', CURRENT_DATE) + INTERVAL '1 week'";
elseif ($periode === 'tahun') $where = "t.created_at >= DATE_TRUNC('year', CURRENT_DATE) AND t.created_at < DATE_TRUNC('year', CURRENT_DATE) + INTERVAL '1 year'";

$stmt = $pdo->query("SELECT COUNT(*) jumlah_transaksi, COALESCE(SUM(t.berat_kg),0) total_kg, COALESCE(SUM(t.total_upah),0) total_upah FROM transaksi_timbang t WHERE $where");
$ringkasan = $stmt->fetch();
$stmt = $pdo->query("SELECT DATE(t.created_at) tanggal, COUNT(*) jumlah_transaksi, COALESCE(SUM(t.berat_kg),0) total_kg, COALESCE(SUM(t.total_upah),0) total_upah FROM transaksi_timbang t WHERE $where GROUP BY DATE(t.created_at) ORDER BY tanggal DESC");
$data = $stmt->fetchAll();
function rp($v){ return 'Rp '.number_format((float)$v,0,',','.'); }
function kg($v){ return number_format((float)$v,2,',','.').' kg'; }
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rekap Produksi - Akunting</title><link href="../assets/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f8f9fa}.sidebar{min-height:100vh;background:#fff;border-right:1px solid #ddd}.brand{color:#198754;font-weight:700}.nav-link{color:#555;border-radius:8px;margin:3px 10px}.nav-link:hover,.nav-link.active{background:#198754;color:#fff}.content{padding:25px}.card{border:0;border-radius:12px}.table th{white-space:nowrap}</style></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 sidebar p-3"><h5 class="brand mb-4">🍤 Pabrik Udang</h5><small class="text-muted px-2">AKUNTING</small><nav class="mt-2"><a class="nav-link" href="dashboard_akunting.php">Dashboard</a><a class="nav-link active" href="rekap_produksi.php">Rekap Produksi</a><a class="nav-link" href="rekap_upah.php">Rekap Upah</a><a class="nav-link" href="histori_produksi_akunting.php">Histori Transaksi</a><a class="nav-link" href="master_tarif.php">Master Tarif</a><a class="nav-link" href="rekap_lembur.php">Rekap Lembur</a><a class="nav-link" href="profil_akunting.php">Profil Akunting</a><a class="nav-link" href="../logout.php">Logout</a></nav></aside><main class="col-md-9 col-lg-10 content"><div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="fw-bold mb-1">Rekap Produksi</h3><p class="text-muted mb-0">Rekap berat produksi berdasarkan periode.</p></div><form><select name="periode" class="form-select" onchange="this.form.submit()"><option value="hari" <?= $periode==='hari'?'selected':'' ?>>Hari Ini</option><option value="minggu" <?= $periode==='minggu'?'selected':'' ?>>Minggu Ini</option><option value="bulan" <?= $periode==='bulan'?'selected':'' ?>>Bulan Ini</option><option value="tahun" <?= $periode==='tahun'?'selected':'' ?>>Tahun Ini</option></select></form></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Total Produksi</small><h3 class="text-success mt-2"><?= kg($ringkasan['total_kg']) ?></h3></div></div><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Jumlah Transaksi</small><h3 class="mt-2"><?= number_format($ringkasan['jumlah_transaksi']) ?></h3></div></div><div class="col-md-4"><div class="card shadow-sm p-4"><small class="text-muted">Total Upah Produksi</small><h3 class="mt-2"><?= rp($ringkasan['total_upah']) ?></h3></div></div></div><div class="card shadow-sm"><div class="card-body"><h5 class="fw-bold mb-3">Rekap Per Hari</h5><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-light"><tr><th>Tanggal</th><th>Transaksi</th><th>Produksi</th><th>Total Upah</th></tr></thead><tbody><?php if(!$data): ?><tr><td colspan="4" class="text-center text-muted py-4">Belum ada data.</td></tr><?php else: foreach($data as $r): ?><tr><td><?= date('d/m/Y',strtotime($r['tanggal'])) ?></td><td><?= number_format($r['jumlah_transaksi']) ?></td><td><?= kg($r['total_kg']) ?></td><td><?= rp($r['total_upah']) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></main></div></div><script src="../assets/js/bootstrap.bundle.min.js"></script></body></html>
